INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 16, 'theory', 'Quiz: RISC-V');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 0, 'What does register x0 (zero) hold?', '["Always zero", "The program counter", "The return address", "The last result"]', 0, 'Writing to x0 changes nothing. The zero register is used for comparisons with zero, for copying, and for a number of pseudo-instructions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 1, 'How many bits does any base RV32I instruction take?', '["8", "16", "32", "64"]', 2, 'All base instructions are 32 bits; the formats R, I, S, B, U and J differ only in how they split into fields.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 2, 'How do you compute the address of word number i in an array?', '["base + i", "base + 4·i (a shift by two bits)", "base · i", "i − base"]', 1, 'A word is four bytes. slli t0, i, 2 multiplies the index by four, and then the base is added.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 3, 'Which registers must a function return unchanged?', '["a0–a7", "t0–t6", "s0–s11", "None of them"]', 2, 'The s registers are "saved": if a function uses them, it saves the values on the stack and restores them. The a and t registers are temporaries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 16, 4, 'How does a program print a character to the trainer''s console?', '["With a print instruction", "By reading the switches", "By writing a byte to the UART address", "With an ecall with no arguments"]', 2, 'Peripherals are connected to the same buses as memory: writing a byte (sb) to the UART address prints it to the console.');
